import fs from 'node:fs'; import assert from 'node:assert/strict'; import YAML from 'yaml';
import {execFileSync} from 'node:child_process'; import {createHash} from 'node:crypto';
const old=YAML.parse(execFileSync('git',['show','HEAD:.github/workflows/security.yml'],{encoding:'utf8'})).jobs.codeql;
const current=YAML.parse(fs.readFileSync('.github/workflows/security.yml','utf8')).jobs.codeql;
const reverted=structuredClone(current), analysis=reverted.steps.find(s=>s.id==='codeql-analyze');
assert.equal(old.steps.find(s=>s.id==='codeql-analyze').env,undefined);
assert.deepEqual(Object.keys(analysis.env),['CODEQL_ACTION_EXTRA_OPTIONS']);
assert.match(analysis.env.CODEQL_ACTION_EXTRA_OPTIONS,/github.job == 'codeql-readonly' && matrix.language == 'rust' && inputs.macro-contexts/u);
delete analysis.env; assert.deepEqual(reverted,old);
const payload=j=>({steps:j.steps,uses:j.uses,with:j.with,strategy:j.strategy});
const hash=j=>createHash('sha256').update(JSON.stringify(payload(j))).digest('hex');
const path='data/benchmarks/fast-pull-request-retained-jobs.json', data=JSON.parse(fs.readFileSync(path,'utf8'));
const rows=data.jobs.filter(r=>r.file==='security.yml'&&r.id==='codeql'); assert.equal(rows.length,1);
assert.equal(rows[0].payloadSha256,hash(old)); rows[0].payloadSha256=hash(current);
fs.writeFileSync(path,JSON.stringify(data,null,2)+'\n');
console.log(JSON.stringify({onlyOptInCacheEnvironmentAdded:true,jobAdmissionAndTimeoutsUnchanged:true,payloadSha256:rows[0].payloadSha256}));

